-- ============================================================
-- 6. 역할-권한 매핑 (CM_ROLE_AUTH) — 107 행
-- SUPER_ADMIN 57 + ADMIN 37 + VIEWER 13
-- ============================================================

-- SUPER_ADMIN: 모든 57 권한
SELECT SEQ_CM_ROLE_AUTH.NEXTVAL,
       (SELECT ROLE_ID FROM CM_ROLE WHERE ROLE_CODE='SUPER_ADMIN'),
       AUTH_CODE,
       'SEED', 'SYSTEM', '127.0.0.1', 'SEED', 'SYSTEM', '127.0.0.1'
  FROM CM_AUTH;

-- ADMIN: 시스템관리 그룹 제외 (37 권한)
SELECT SEQ_CM_ROLE_AUTH.NEXTVAL,
       (SELECT ROLE_ID FROM CM_ROLE WHERE ROLE_CODE='ADMIN'),
       AUTH_CODE,
       'SEED', 'SYSTEM', '127.0.0.1', 'SEED', 'SYSTEM', '127.0.0.1'
  FROM CM_AUTH
 WHERE AUTH_CODE NOT LIKE 'CODE\_%' ESCAPE '\'
   AND AUTH_CODE NOT LIKE 'MENU\_%' ESCAPE '\'
   AND AUTH_CODE NOT LIKE 'ROLE\_%' ESCAPE '\'
   AND AUTH_CODE NOT LIKE 'AUTH\_%' ESCAPE '\'
   AND AUTH_CODE NOT LIKE 'USER\_%' ESCAPE '\';

-- VIEWER: 일반 도메인 *_VIEW 만 (13 권한 — 시스템관리 *_VIEW 제외)
SELECT SEQ_CM_ROLE_AUTH.NEXTVAL,
       (SELECT ROLE_ID FROM CM_ROLE WHERE ROLE_CODE='VIEWER'),
       AUTH_CODE,
       'SEED', 'SYSTEM', '127.0.0.1', 'SEED', 'SYSTEM', '127.0.0.1'
  FROM CM_AUTH
 WHERE AUTH_TYPE = 'VIEW'
   AND AUTH_CODE NOT IN ('CODE_VIEW', 'MENU_VIEW', 'ROLE_VIEW', 'AUTH_VIEW', 'USER_VIEW');

COMMIT;

-- ============================================================
-- 완료 메시지
